// Function Object (Functor) Definition
struct Multiplier {
    int factor = 2;
    int operator()(int x) const { return x * factor; }
};
int result = Multiplier()(5); // Functor instantiation and call

// Adapting Member Functions using std::mem_fun_ref
struct Widget {
    void process() const;
};
std::vector<Widget> items;

// Adapter for calling member function on object references (C++17+)
// Note: Often used with std::for_each or std::transform
std::for_each(items.begin(), items.end(),
              std::mem_fun_ref(&Widget::process));
